export const firebaseConfig = new FirebaseService();

// ── Named-export adapter ────────────────────────────────────────────────────
// Page controllers, account.js and js/firebase.js (the shim that
// stripe-paywall.js imports) expect these named exports. Without them every
// module graph fails to link and no tool page runs. They wrap the
// FirebaseService above and degrade to no-ops when the compat SDK is absent.

export let auth = null;
export let db = null;
export const analytics = null;

let _initPromise = null;

export function initFirebase() {
  if (!_initPromise) {
    _initPromise = firebaseConfig.initialize()
      .then((ok) => {
        if (!ok) return null;
        auth = firebaseConfig.getAuth();
        db = firebaseConfig.getFirestore();
        return firebaseConfig.getCurrentUser();
      })
      .catch(() => null);
  }
  return _initPromise;
}

export async function saveToHistory(toolName, metadata = {}) {
  try {
    await initFirebase();
    return await firebaseConfig.saveDocument({ tool: toolName, ...metadata });
  } catch (e) {
    return null;
  }
}

export async function getHistory(toolName = null, maxItems = 20) {
  try {
    await initFirebase();
    const items = await firebaseConfig.getDocumentHistory(maxItems);
    return toolName ? items.filter((i) => i.tool === toolName) : items;
  } catch (e) {
    return [];
  }
}
